column2:
=LET(
  items; SPLIT("🪅,💝,🎉,🧃,🦖,🎈,🎁,🎊,🏆,🥳,🪄,⚡,🏀,🏎️,🎮,🐉,🚀,🪁,🏹,🎯,🦁,🐵,🏰,🛹,🏓,🐢,🦕"; ",");
  TEXTJOIN(" "; TRUE; INDEX(items; RANDBETWEEN(1; COUNTA(items))))
)

